import { VyiInputData, VyiData } from './types';
import { WORKER_CODE } from './generated/vyi-worker-inline';

// Create a Blob URL from the inlined worker code
// This makes the worker work in any project context (not just node_modules)
const WORKER_BLOB = new Blob([WORKER_CODE], { type: 'application/javascript' });
const WORKER_SCRIPT_URL = URL.createObjectURL(WORKER_BLOB);

/**
 * Singleton worker pool - shared across all VyiWorker instances
 * @internal
 */
class WorkerPool {
  private static instance: WorkerPool | null = null;
  private workers: Worker[] = [];
  private availableWorkers: Worker[] = [];
  private maxWorkers: number;
  private messageId = 0;
  private pendingMessages = new Map<string, {
    resolve: (value: any) => void;
    reject: (error: Error) => void;
  }>();

  private waitQueue: ((worker: Worker) => void)[] = [];

  private constructor(maxWorkers = navigator.hardwareConcurrency || 4) {
    this.maxWorkers = maxWorkers;
    this.initializeWorkers();
  }

  static getInstance(maxWorkers?: number): WorkerPool {
    if (!WorkerPool.instance) {
      WorkerPool.instance = new WorkerPool(maxWorkers);
    }
    return WorkerPool.instance;
  }

  static destroy(): void {
    if (WorkerPool.instance) {
      WorkerPool.instance.terminate();
      WorkerPool.instance = null;
    }
  }

  private initializeWorkers(): void {
    for (let i = 0; i < this.maxWorkers; i++) {
      const worker = this.createWorker();
      this.workers.push(worker);
      this.availableWorkers.push(worker);
    }
  }

  private createWorker(): Worker {
    // Create worker from the bundled worker file
    // In browser environments, this will load the worker from the dist folder
    const worker = new Worker(WORKER_SCRIPT_URL, { type: 'module' });

    worker.onmessage = (event) => {
      const { id, success, data, error } = event.data;
      const pending = this.pendingMessages.get(id);

      if (pending) {
        this.pendingMessages.delete(id);
        if (success) {
          pending.resolve(data);
        } else {
          pending.reject(new Error(error));
        }
      }
    };

    worker.onerror = (error) => {
      console.error('Worker error:', error);
      for (const [id, pending] of this.pendingMessages) {
        pending.reject(new Error(`Worker error: ${error.message}`));
      }
      this.pendingMessages.clear();
    };

    return worker;
  }

  async getWorker(): Promise<Worker> {
    if (this.availableWorkers.length > 0) {
      return this.availableWorkers.pop()!;
    }

    if (this.workers.length === 0) {
      throw new Error('Workers have been terminated. Create a new VyiWorker instance to continue.');
    }

    // Wait for a worker to become available using a queue
    return new Promise((resolve) => {
      this.waitQueue.push(resolve);
    });
  }

  returnWorker(worker: Worker): void {
    if (this.waitQueue.length > 0) {
      // If there are waiting tasks, give the worker directly to the next one
      const resolve = this.waitQueue.shift()!;
      resolve(worker);
    } else if (this.workers.includes(worker)) {
      // Otherwise put it back in the pool
      this.availableWorkers.push(worker);
    }
  }

  async sendMessage(worker: Worker, type: string, data: any): Promise<any> {
    const id = `${this.messageId++}`;

    return new Promise((resolve, reject) => {
      this.pendingMessages.set(id, { resolve, reject });
      worker.postMessage({ id, type, data });

      // Set a timeout to prevent hanging forever
      setTimeout(() => {
        if (this.pendingMessages.has(id)) {
          this.pendingMessages.delete(id);
          reject(new Error('Worker message timeout'));
        }
      }, 30000); // 30 second timeout
    });
  }

  terminate(): void {
    for (const worker of this.workers) {
      worker.terminate();
    }
    this.workers = [];
    this.availableWorkers = [];

    // Reject all pending messages
    for (const [id, pending] of this.pendingMessages) {
      pending.reject(new Error('Worker terminated'));
    }
    this.pendingMessages.clear();
  }
}

export class VyiWorker {
  /** @internal */
  private pool: WorkerPool;

  constructor(maxWorkers?: number) {
    this.pool = WorkerPool.getInstance(maxWorkers);
  }

  async parse(data: VyiInputData): Promise<VyiData> {
    const worker = await this.pool.getWorker();
    try {
      const result = await this.pool.sendMessage(worker, 'parse', data);
      return result;
    } finally {
      this.pool.returnWorker(worker);
    }
  }

  async parseMultiple(dataArray: VyiInputData[]): Promise<VyiData[]> {
    const promises = dataArray.map(data => this.parse(data));
    return Promise.all(promises);
  }

  async parseMultipleWithProgress(
    dataArray: VyiInputData[],
    onProgress?: (completed: number, total: number) => void
  ): Promise<VyiData[]> {
    const total = dataArray.length;
    let completed = 0;

    const promises = dataArray.map(async (data) => {
      try {
        const result = await this.parse(data);
        completed++;
        onProgress?.(completed, total);
        return result;
      } catch (error) {
        completed++;
        onProgress?.(completed, total);
        throw error;
      }
    });

    return Promise.all(promises);
  }

  getAvailableWorkerCount(): number {
    return this.pool['availableWorkers'].length;
  }

  getTotalWorkerCount(): number {
    return this.pool['workers'].length;
  }

  getStatus(): { totalWorkers: number; availableWorkers: number } {
    return {
      totalWorkers: this.pool['workers'].length,
      availableWorkers: this.pool['availableWorkers'].length
    };
  }

  terminate(): void {
    this.pool.terminate();
  }
}

export function getVyiWorker(maxWorkers?: number): VyiWorker {
  return new VyiWorker(maxWorkers);
}

export function terminateVyiWorker(): void {
  WorkerPool.destroy();
}
