import { VYI } from './vyi';
import { Frame } from './frame';
import { IconData, StateData, FrameData } from './types';
import { IconPoint, type Point, type Bounds, type PositionalPoint, type IconPointExport } from './vendor/icon-point';
import { CircleShape, RectShape, PolygonShape } from './types';
import { BoundsManager } from './bounds/bounds-manager';

/**
 * Icon class for managing individual icons within a VYI file
 */
export class Icon {
    /**
     * A map of icons that are state of this icon.
     */
    states = new Map<string, Icon>();
    /**
     * A map of frames that are the frames of this icon.
     */
    frames = new Map<number, Frame>();
    /**
     * The width of this icon. All states and frames of this icon must match this size.
     */
    width: number = 32;
    /**
     * The height of this icon. All states and frames of this icon must match this size.
     */
    height: number = 32;
    /**
     * The data URL of the sprite in this frame.
     */
    dataURL: string = '';
    /**
     * The delay of this frame.
     */
    delay: number = 100;
    /**
     * The name of this icon.
     */
    name: string = '';
    /**
     * The icon that owns this icon. This means this icon is state. 
     */
    parent: Icon | null = null;
    /**
     * The vyi this icon belongs to.
     */
    vyi: VYI | null = null;
    /**
     * A random unique Id attached to each icon to distinguish them from others in the event another icon shares the same name.
     */
    id: string = '';
    /**
     * An set of used Ids to prevent collusion between duplicate named icons.
     */
    static reservedIds = new Set<string>();

    /** A set of icon points belonging to this icon. */
    iconPoints: Set<IconPoint> = new Set();

    /** The bounds of this icon. */
    boundsManager: BoundsManager = new BoundsManager();

    /**
     * A set of reserved icon point IDs that cannot be used for additional icon points or removed.
     */
    static reservedIconPointIds = new Set<string>(['center', 'top-left', 'top-right', 'bottom-left', 'bottom-right', 'top-middle', 'bottom-middle', 'left-middle', 'right-middle']);

    /**
    * Generates a UUID (Universally Unique Identifier) version 4.
    * 
    * @returns The generated UUID.
    */
    static generateId(): string {
        const genId = () => {
            return Math.floor(Math.random() * 0xFFFFFFFF).toString(16).padStart(8, '0');
        }

        let id = genId();
        while (this.reservedIds.has(id)) {
            id = genId();
        }
        this.reservedIds.add(id);
        return id;
    }
    /**
     * Creates this icon instance.
     * @param pIconData - The icon data that is used to build this icon.
     */
    constructor(pIconData?: IconData) {
        if (pIconData) {
            this.parse(pIconData);
        }
        this.assignId();
    }
    /**
     * Sets the parent for this state.
     * @param pParent - The parent icon of this state.
     */
    private setParent(pParent: Icon): void {
        if (!pParent || this.parent) return;
        if (pParent instanceof Icon) {
            this.parent = pParent;
        }
    }
    /**
     * Removes the parent and vyi from this state.
     */
    private removeParent(): void {
        if (this.parent) {
            this.parent = null;
            this.vyi = null;
        }
    }
    /**
     * Sets the vyi of this icon.
     * 
     * @param pVyi - The vyi that owns this icon.
     */
    setVyi(pVyi: VYI): void {
        if (!pVyi) return;

        if (pVyi instanceof VYI) {
            this.vyi = pVyi;

            if (this.getStateCount() > 0) {
                const states = this.getStates();
                states.forEach((pState) => {
                    pState.setParent(this);
                    pState.setVyi(pVyi);
                });
            }

            const frames = this.getFrames();
            frames.forEach((pFrame) => pFrame.setParent(this));
        }
    }
    /**
     * Removes the vyi from this icon.
     */
    removeVyi(): void {
        this.vyi = null;
    }
    /**
     * Assigns an Id to this icon.
     */
    private assignId(): void {
        this.id = Icon.generateId();
    }
    /**
     * Gets the id of this icon.
     * @returns The id of this icon.
     */
    getId(): string {
        return this.id;
    }
    /**
     * Gets the vyi this icon belongs to.
     * @returns The vyi this icon belongs to.
     */
    getVyi(): VYI | null {
        return this.vyi;
    }
    /**
     * Gets the icon this state belongs to. If this icon is not a state, it will return undefined.
     * @returns The icon this state belongs to.
     */
    getParent(): Icon | null {
        return this.parent;
    }
    /**
     * Gets the number of states this icon has.
     * @returns The amount of states this icon has.
     */
    getStateCount(): number {
        return this.states.size;
    }
    /**
     * Gets the number of frames this icon has.
     * @returns The amount of frames this icon has.
     */
    getFrameCount(): number {
        return this.frames.size;
    }
    /**
     * Parses through the icon data and adds data to this icon.
     * @param pIconData - The icon data that is used to build this icon.
     */
    parse(pIconData: IconData): void {
        if (!pIconData) return;

        // Loop through the icon data and create this icon
        const iconName = pIconData[0];
        const iconWidth = pIconData[1];
        const iconHeight = pIconData[2];
        const iconDelay = pIconData[3];
        const iconDataURL = pIconData[4];
        const frameArray = pIconData[5];
        const stateArray = pIconData[6];
        // Meta data (not apart of the vyi spec)
        const iconPointArray = pIconData[7];
        const boundsData = pIconData[8];

        // Set name
        this.rename(iconName);
        // Set size
        this.setSize(iconWidth, iconHeight);
        // Set icon delay
        this.setDelay(iconDelay);
        // Set dataURL
        this.setDataURL(iconDataURL);

        if (Array.isArray(frameArray)) {
            // If the frame array has data then we need to store it.
            frameArray.forEach((pFrame) => {
                // pFrame is an array holding the datalURL and frameDelay of the frame
                this.addFrame(pFrame);
            });
        }

        if (Array.isArray(stateArray)) {
            // If the state array has data then we need to store it.
            stateArray.forEach((pStateData) => {
                const state = new Icon(undefined);
                const stateName = pStateData[0];
                const stateDataURL = pStateData[1];
                const stateDelay = pStateData[2];
                const stateFrameArray = pStateData[3];
                const stateBoundsData = pStateData[4];

                state.rename(stateName);
                state.setSize(iconWidth, iconHeight);
                state.setDelay(stateDelay);
                state.setDataURL(stateDataURL);

                if (Array.isArray(stateFrameArray)) {
                    stateFrameArray.forEach((pFrame) => {
                        state.addFrame(pFrame);
                    });
                }

                // Load state bounds if they exist
                if (stateBoundsData && typeof stateBoundsData === 'object') {
                    state.boundsManager.loadBounds(stateBoundsData);
                }

                this.addState(state);
            });
        }

        if (Array.isArray(iconPointArray)) {
            // If the icon point array has data then we need to store it.
            iconPointArray.forEach((pIconPoint) => {
                const { x, y, width, height, id } = pIconPoint;
                // Skip reserved icon points as they will be set automatically
                if (Icon.reservedIconPointIds.has(id)) return;
                this.addIconPoint({ x: 0, y: 0 }, { width, height }, { x, y }, id);
            });
        }

        // Load bounds if they exist
        if (boundsData && typeof boundsData === 'object') {
            this.boundsManager.loadBounds(boundsData);
        }

        this.resetInitialIconPoints();
    }

    /**
     * Sets the initial icon points for this icon.
     */
    public resetInitialIconPoints(): void {
        const width = this.getWidth();
        const height = this.getHeight();

        // Remove all reserved icon points first
        Array.from(Icon.reservedIconPointIds).forEach((pId) => {
            const iconPoint = Array.from(this.iconPoints).find((pPoint) => pPoint.getId() === pId);
            if (!iconPoint) return;
            this.iconPoints.delete(iconPoint);
        });

        // Force add the center icon point
        const initialPoint = { x: 1, y: 1 };
        const centerIconPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: Math.round(width / 2), y: Math.round(height / 2) }, 'center');
        const tlPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: 1, y: 1 }, 'top-left');
        const trPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: width, y: 1 }, 'top-right');
        const blPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: 1, y: height }, 'bottom-left');
        const brPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: width, y: height }, 'bottom-right');
        const topMidPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: Math.round(width / 2), y: 1 }, 'top-middle');
        const bottomMidPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: Math.round(width / 2), y: height }, 'bottom-middle');
        const leftMidPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: 1, y: Math.round(height / 2) }, 'left-middle');
        const rightMidPoint = new IconPoint(initialPoint, { width: width, height: height }, { x: width, y: Math.round(height / 2) }, 'right-middle');

        this.iconPoints.add(centerIconPoint);
        this.iconPoints.add(tlPoint);
        this.iconPoints.add(trPoint);
        this.iconPoints.add(blPoint);
        this.iconPoints.add(brPoint);
        this.iconPoints.add(topMidPoint);
        this.iconPoints.add(bottomMidPoint);
        this.iconPoints.add(leftMidPoint);
        this.iconPoints.add(rightMidPoint);
    }

    /**
     * Creates a new IconPoint from the provided geometry and identifier, adds it to this instance's
     * iconPoints collection, and returns the newly created object.
     *
     * @param pPoint - The location of the icon in coordinate space.
     * @param pBounds - The bounds that apply to or contain the icon point.
     * @param pIconPoint - The icon point position relative to the bounds.
     * @param pId - A string id for the icon point.
     * @returns The created IconPoint that was added to this.iconPoints.
     */
    addIconPoint(pPoint: Point, pBounds: Bounds, pIconPoint: PositionalPoint, pId: string): IconPoint | void {
        if (Icon.reservedIconPointIds.has(pId)) {
            VYI.logger.prefix('Vyi-module').error(`The id ${pId} is reserved and cannot be used for additional icon points.`);
            return;
        }

        const iconPoint = new IconPoint(pPoint, pBounds, pIconPoint, pId);
        this.iconPoints.add(iconPoint);
        return iconPoint;
    }
    /**
     * Removes an icon point from this icon by its id.
     * @param pId - The id of the icon point to remove.
     */
    removeIconPoint(pId: string): void {
        for (const iconPoint of this.iconPoints) {
            if (iconPoint.getId() === pId && !Icon.reservedIconPointIds.has(pId)) {
                this.iconPoints.delete(iconPoint);
                break;
            }
        }
    }
    /**
     * Gets an icon point by its id.
     * @param pId - The id of the icon point to get.
     * @returns - The icon point with the matching id, or undefined if not found.
     */
    getIconPointExportById(pId: string): IconPointExport | void {
        for (const iconPoint of this.iconPoints) {
            if (iconPoint.getId() === pId) {
                return iconPoint.export();
            }
        }
        return;
    }
    /**
     * Gets the icon point data of all icon points belonging to this icon.
     * @returns - An array of icon point data.
     */
    getIconPointsExport(): IconPointExport[] {
        const points = [] as IconPointExport[];
        this.iconPoints.forEach((pPoint) => points.push(pPoint.export()));
        return points;
    }

    /**
     * Gets an icon point by its id.
     * @param pId - The id of the icon point to get.
     * @returns - The icon point with the matching id, or undefined if not found.
     */
    getIconPointById(pId: string): IconPoint | void {
        for (const iconPoint of this.iconPoints) {
            if (iconPoint.getId() === pId) {
                return iconPoint;
            }
        }
        return;
    }
    /**
     * Gets the icon point data of all icon points belonging to this icon.
     * @returns - An array of icon point data.
     */
    getIconPoints(): IconPoint[] {
        const points = [] as IconPoint[];
        this.iconPoints.forEach((pPoint) => points.push(pPoint));
        return points;
    }
    /**
     * Gets all bounds of this icon.
     * @returns An object containing all bounds by their IDs.
     */
    getBoundsExport(): Record<string, CircleShape | RectShape | PolygonShape> {
        return this.boundsManager.exportAll();
    }
    /**
     * Gets a specific bounds by its id.
     * @param pId - The id of the bounds to get.
     * @returns - The bounds with the matching id, or undefined if not found.
     */
    getBoundsById(pId: string): CircleShape | RectShape | PolygonShape | undefined {
        return this.boundsManager.get(pId);
    }
    /**
     * Gets all bounds of this icon.
     * @returns An object containing all bounds by their IDs.
     */
    getIdsByShape(pShape: 'circle' | 'rect' | 'polygon'): string[] {
        return this.boundsManager.getIdsByShape(pShape);
    }
    /**
     * Sets the bounds of this icon.
     * @param pId - The ID for the bounds.
     * @param pShape - The bounds shape object.
     * @returns This icon instance.
     */
    setBounds(pId: string, pShape: CircleShape | RectShape | PolygonShape): this {
        this.boundsManager.add(pId, pShape);
        return this;
    }
    /**
     * Removes a bounds from this icon.
     * @param pId - The ID of the bounds to remove.
     * @returns This icon instance.
     */
    removeBounds(pId: string): this {
        this.boundsManager.remove(pId);
        return this;
    }
    /**
     * Updates the bounds of this icon.
     * @param pId - The ID of the bounds to update.
     * @param pShape - The partial bounds shape to update.
     * @returns This icon instance.
     */
    updateBounds(pId: string, pShape: Partial<CircleShape | RectShape | PolygonShape>): this {
        this.boundsManager.update(pId, pShape);
        return this;
    }

    /**
     * Sets the size of this icon.
     * @param pWidth - The width of this icon.
     * @param pHeight - The height of this icon.
     * @returns This icon instance.
     */
    setSize(pWidth: number, pHeight: number): this {
        if (typeof pWidth === 'number') {
            this.width = pWidth;
        }
        if (typeof pHeight === 'number') {
            this.height = pHeight;
        }
        return this;
    }
    /**
     * Gets the width of the icon.
     * @returns The width of the icon.
     */
    getWidth(): number {
        return this.width;
    }
    /**
     * Gets the height of the icon.
     * @returns The height of the icon.
     */
    getHeight(): number {
        return this.height;
    }
    /**
     * Gets the width and height of this icon and returns it.
     * @returns An object with the width and height of this icon.
     */
    getSize(): { width: number; height: number } {
        return { width: this.width, height: this.height };
    }
    /**
     * Sets the data url of this icon.
     * @param pDataURL - The base64 data of this image.
     * @returns This icon instance.
     */
    setDataURL(pDataURL: string): this {
        if (typeof pDataURL === 'string') {
            // Strip data:image/*;base64, prefix if present
            this.dataURL = pDataURL.replace(/^data:image\/[a-z]+;base64,/, '');
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid data url type!');
        }
        return this;
    }
    /**
     * Gets the data URL of this icon.
     * @returns The base64 data of this image.
     */
    getDataURL(): string {
        return this.dataURL;
    }
    /**
     * Sets the frame delay of this icon.
     * @param pDelay - The delay to set this frame to.
     * @returns This icon instance.
     */
    setDelay(pDelay: number): this {
        if (typeof pDelay === 'number') {
            this.delay = pDelay;
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid delay type!');
        }
        return this;
    }
    /**
     * Gets the delay of this icon.
     * @returns The delay of this icon.
     */
    getDelay(): number {
        return this.delay;
    }
    /**
     * Changes the name of this icon.
     * @param pName - The new name of the icon.
     * @returns This icon instance.
     */
    rename(pName: string): this {
        if (typeof pName === 'string') {
            // Decode URL-encoded names (e.g., "Mansion%20Floor%201" -> "Mansion Floor 1")
            try {
                this.name = decodeURIComponent(pName);
            } catch {
                // If decoding fails, use the original name
                this.name = pName;
            }
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid type for pName!');
        }
        return this;
    }
    /**
     * Returns the name of this icon.
     * @returns The name of this icon.
     */
    getName(): string {
        return this.name;
    }
    /**
     * Sets all the frames belonging to this icon to the same delay.
     * @param pDelay - The delay to set all frames to.
     * @returns This icon instance.
     */
    setAllFrameDelays(pDelay: number): this {
        if (typeof pDelay === 'number') {
            this.setDelay(pDelay);
            this.getFrames().forEach((pFrame) => pFrame.setDelay(pDelay));
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid type for pDelay!');
        }
        return this;
    }
    /**
     * Adds a new frame to this icon.
     * @param pFrameData - The frame data to give this frame.
     * @returns The frame that was added or undefined.
     */
    addFrame(pFrameData: Frame | FrameData): Frame | undefined {
        if (!pFrameData) {
            VYI.logger.prefix('Vyi-module').error('No frame data passed!');
            return undefined;
        }

        if (!(pFrameData instanceof Frame) && !Array.isArray(pFrameData)) {
            VYI.logger.prefix('Vyi-module').error('Invalid frame data type passed!');
            return undefined;
        }

        // Create the icon instance
        const frame = pFrameData instanceof Frame
            ? pFrameData
            : new Frame(pFrameData);


        frame.setParent(this);
        this.frames.set(this.frames.size, frame);
        this.indexFrames();

        return frame;
    }
    /**
     * Removes the frame passed.
     * @param pFrame - The frame to remove from this icon.
     * @returns This icon instance.
     */
    removeFrame(pFrame: Frame): this {
        if (!pFrame) return this;
        if (pFrame instanceof Frame) {
            if (this.frames.delete(pFrame.index)) {
                pFrame.removeParent();
                this.indexFrames();
            }
        }
        return this;
    }
    /**
     * Removes the frame via it's index.
     * @param pIndex - The index of the frame to remove.
     * @returns This icon instance.
     */
    removeFrameByIndex(pIndex: number): this {
        const frame = this.getFrame(pIndex);
        if (frame) {
            this.removeFrame(frame);
        }
        return this;
    }
    /**
     * Index the frames properly.
     */
    private indexFrames(): void {
        const frames = this.getFrames();
        this.frames.clear();
        frames.forEach((pFrame, pIndex) => {
            pFrame.index = pIndex;
            this.frames.set(pIndex, pFrame);
        });
    }
    /**
     * Reorders the frame in the animation. The index of the passed frame will be swapped with the frame at pIndex.
     * The "first" frame of the animation is technically this icon's dataURL. So if you are aiming to change the order of this icon and convert it into a frame.
     * pCurrentIndex must be set to -1 to match this icon.
     * 
     * @param pCurrentIndex - The current index of the frame.
     * @param pIndex - The index the frame will be moving to.
     * @returns This icon instance.
     */
    reorderFrame(pCurrentIndex: number, pIndex: number): this {
        if (typeof pCurrentIndex === 'number' && typeof pIndex === 'number') {
            let frameAtIndex = this.getFrame(pIndex);
            let currentFrame = pCurrentIndex === -1
                ? this
                : this.getFrame(pCurrentIndex)

            // If both frames can be found, we can swap their data.
            if (currentFrame && frameAtIndex) {
                // Store frame data
                const currentFrameDataURL = currentFrame.getDataURL();
                const currentFrameDelay = currentFrame.getDelay();

                const frameAtIndexDataURL = frameAtIndex.getDataURL();
                const frameAtIndexDelay = frameAtIndex.getDelay();

                // Swap data from frame
                currentFrame.setDataURL(frameAtIndexDataURL);
                currentFrame.setDelay(frameAtIndexDelay);

                // Swap data to frame
                frameAtIndex.setDataURL(currentFrameDataURL);
                frameAtIndex.setDelay(currentFrameDelay);
            } else {
                VYI.logger.prefix('Vyi-module').error('There was no frame found at pCurrentIndex, or there was no frame found at pIndex!');
            }
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid type used!');
        }
        return this;
    }
    /**
     * Gets the frame existing at pIndex.
     * Frame 0 will actually be frame "1" in the animation. As this icon will actually be frame 0.
     * If you are trying to get "frame" 1. Then you will need to use the icon's delay and data url. As that is frame 0.
     * @param pIndex - The index of the frame to get.
     * @returns The frame found at pIndex.
     */
    getFrame(pIndex: number): Frame | undefined {
        return this.frames.get(pIndex);
    }
    /**
     * Returns an array of all the frames this icons has.
     * @returns An array of frames this icon has.
     */
    getFrames(): Frame[] {
        return Array.from(this.frames.values());
    }
    /**
     * Gets all the frames belonging to this icon.
     * @returns An array containing the frame data of all frames.
     */
    private getFramesData(): any[] {
        const frameDataArray = this.getFrames().map((pFrame) => pFrame.export());
        return frameDataArray;
    }
    /**
     * Adds this icon data as a state. A state is also an icon.
     * @param pIconData - The data used to create this state icon.
     * @returns The state that was added or undefined.
     */
    addState(pIconData: Icon | StateData): Icon | undefined {
        if (!pIconData) {
            VYI.logger.prefix('Vyi-module').error('No icon data passed!');
            return undefined;
        }

        if (!(pIconData instanceof Icon) && !Array.isArray(pIconData)) {
            VYI.logger.prefix('Vyi-module').error('Invalid icon data type passed!');
            return undefined;
        }

        // Create the icon instance
        const state = pIconData instanceof Icon
            ? pIconData
            : new Icon(this.convertStateDataToIconData(pIconData));

        if (state.getWidth() !== this.getWidth() || state.getHeight() !== this.getHeight()) {
            VYI.logger.prefix('Vyi-module').error('State dimensions do not match parent!');
            return undefined;
        }

        state.setParent(this);
        if (this.vyi) {
            state.setVyi(this.vyi);
        }
        this.states.set(state.id, state);

        return state;
    }
    /**
     * Removes the state passed.
     * @param pState - The state to remove from this icon.
     * @returns This icon instance.
     */
    removeState(pState: Icon): this {
        if (pState instanceof Icon) {
            if (this.states.delete(pState.id)) {
                ;
                pState.removeParent();
            }
        }
        return this;
    }
    /**
     * Removes the state via it's name. The LAST defined icon that has the passed name will be removed. As names are not unique.
     * @param pName - The name to use to find the state.
     * @returns This icon instance.
     */
    removeStateByName(pName: string): this {
        const state = this.getState(pName);
        if (state) {
            this.removeState(state);
        }
        return this;
    }
    /**
     * Removes the state via it's id.
     * @param pId - The id to use to find the state.
     * @returns This icon instance.
     */
    removeStateById(pId: string): this {
        const state = this.getStateById(pId);
        if (state) {
            this.removeState(state);
        }
        return this;
    }
    /**
     * Gets the state that has the name pName. The LAST defined state that has the passed name will be returned.
     * @param pName - The name of the state to get.
     * @returns The state that has the name of pName.
     */
    getState(pName: string): Icon | undefined {
        if (typeof pName === 'string') {
            const states = this.getStates();
            for (let i = states.length - 1; i >= 0; i--) {
                const state = states[i];
                // If the icon has the same name, return that icon
                if (state.getName() === pName) {
                    return state;
                }
            }
            return undefined;
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid name type used!');
            return undefined;
        }
    }
    /**
     * Gets the state by the id provided.
     * @param pId - The id of the state.
     * @returns The state that has the id that was passed.
     */
    getStateById(pId: string): Icon | undefined {
        if (!pId) return;
        return this.states.get(pId);
    }
    /**
     * Returns an array of all the states this icon has.
     * @returns An array of states this icon has.
     */
    getStates(): Icon[] {
        return Array.from(this.states.values());
    }
    /**
     * Returns an array of all the state names this icon has.
     * @returns An array of the state names.
     */
    getStateNames(): string[] {
        return this.getStates().map((pState) => pState.getName());
    }
    /**
     * Gets all the states belonging to this icon.
     * @returns An array containing the state data of all frames.
     */
    private getStatesData(): any[] {
        const stateDataArray = this.getStates().map((pState) => pState.exportAsState());
        return stateDataArray;
    }
    /**
     * Exports this icon as if it was a state in the proper vyi format.
     * @returns An array of data related to this icon as if it were a state.
     */
    private exportAsState(): StateData {
        const stateData: StateData = [
            this.getName(),
            this.getDataURL(),
            this.getDelay(),
            this.getFrames().map((pFrame) => pFrame.export())
        ];

        // Include bounds if any exist for this state
        const boundsExport = this.getBoundsExport();
        if (Object.keys(boundsExport).length > 0) {
            stateData[4] = boundsExport;
        }

        return stateData;
    }
    /**
     * Converts StateData to IconData format
     * @param stateData - The state data to convert
     * @returns IconData format
     */
    private convertStateDataToIconData(stateData: StateData): IconData {
        return [
            stateData[0], // name
            this.getWidth(), // width (use parent's width)
            this.getHeight(), // height (use parent's height)
            stateData[2], // delay
            stateData[1], // dataURL
            stateData[3] // frameArray
        ];
    }

    /**
     * Exports this icon's data into proper vyi format.
     * @returns An array of data related to this icon in the proper vyi format.
     */
    export(): IconData {
        const iconData: IconData = [
            this.getName(),
            this.getWidth(),
            this.getHeight(),
            this.getDelay(),
            this.getDataURL(),
            this.getFramesData()
        ];

        // This is actually an optional data entry into the vyi, only used if states actually exist on this icon.
        if (this.states.size > 0) {
            iconData[6] = this.getStatesData();
        }

        // Store icon points here
        iconData[7] = this.getIconPointsExport();
        // Store polygon bounds here
        iconData[8] = this.getBoundsExport();
        return iconData;
    }
}