import { Logger } from './vendor/logger';
import { Icon } from './icon';
import { VyiData, VyiInputData, IconData } from './types';
// @ts-ignore - pako doesn't have proper TypeScript definitions
import pako from './vendor/pako.esm.mjs';

/**
 * VYI class for managing .vyi files
 */
export class VYI {
    /**
     * The version of the module.
     */
    static version = "VERSION_REPLACE_ME";
    /** The logger module this module uses to log errors / logs. */
    static logger = new Logger();
    /**
     * A map of icons that belong to this VYI
     */
    icons = new Map<string, Icon>();
    /**
     * The name of this vyi.
     */
    name: string = 'failed-to-find-vyi-name';
    /**
     * The version of the VYI.
     */
    formatVersion: number = 1;
    /**
     * Initializes this module with the information from the VYI passed.
     * @param pVyiData - A JSON / Javascript object containing the vyi information.
     */
    constructor(pVyiData?: VyiInputData) {
        VYI.logger.registerType('Vyi-module', '#ff6600');
        if (pVyiData) {
            this.parse(pVyiData);
        }
    }
    /**
     * Parses the provided VYI data (either a URL, a JSON object, or binary data) and processes it.
     * If the data is a URL (string), it fetches/reads the data and parses it as JSON.
     * If the data is binary, it attempts to inflate it using pako or decode it as plain text.
     *
     * @param pVyiData - The VYI data to parse. Or a path to a VYI file.
     * @returns A promise that resolves when the parsing is completed.
     * @throws Throws an error if fetching, inflating, or decoding fails.
     */
    parse(pVyiData: VyiInputData): VYI {
        if (!pVyiData) return this;

        try {
            let vyi;

            if (typeof pVyiData === 'string') {
                try {
                    vyi = JSON.parse(pVyiData);
                } catch (pError) {
                    // Binary string
                    if (!pVyiData.includes('.vyr') && !pVyiData.includes('.vyi')) {
                        vyi = pVyiData;
                        if (!vyi) {
                            throw new Error('Non vyi data found from binary string');
                        }
                    } else {
                        // For string input, try to parse as JSON first
                        try {
                            vyi = JSON.parse(pVyiData);
                        } catch (e) {
                            // If JSON parsing fails, treat as file path (Node.js only)
                            const isNodeEnv = typeof window === 'undefined';
                            if (isNodeEnv) {
                                vyi = this.readFileAndGetVYI(pVyiData);
                            } else {
                                throw new Error('Invalid string input - not valid JSON or file path');
                            }
                        }
                    }
                }
            } else if (pVyiData instanceof VYI) {
                vyi = pVyiData.export();
            } else if (pVyiData instanceof Object && !Array.isArray(pVyiData) && !(pVyiData instanceof ArrayBuffer || pVyiData instanceof Uint8Array)) {
                vyi = pVyiData;
            } else if (pVyiData instanceof ArrayBuffer || pVyiData instanceof Uint8Array) {
                vyi = this.handleBinaryData(pVyiData);
            } else {
                throw new Error('Error processing: Invalid input type provided.');
            }

            // @ts-ignore - Handle old format
            if (!vyi || ((!vyi.v || !vyi.i) && !vyi.icons)) {
                throw new Error('Non vyi data found.');
            }

            this.processVyiData(vyi);
        } catch (pError) {
            VYI.logger.prefix('Vyi-module').error(`${(pError as Error).message}`);
        }

        return this;
    }
    /**
     * Read the file from a binary string.
     * @param pVyiData - The compressed binary string representing the vyi data.
     * @returns An vyi that was compressed in the file.
     */
    readFile(pVyiData: string): any {
        try {
            // Convert string to Uint8Array for decompression
            const encoder = new TextEncoder();
            const binaryData = encoder.encode(pVyiData);
            const decompressed = pako.inflate(binaryData, { to: 'string' });
            return JSON.parse(decompressed);
        } catch (error) {
            console.error('File reading failed:', error);
            return null;
        }
    }
    /**
     * Reads a file and returns the vyi from it.
     * @param pURL - The URL to read the data from.
     * @returns The vyi from the file.
     */
    private readFileAndGetVYI(pURL: string): any {
        const fs = require('fs');
        const data = fs.readFileSync(pURL);
        return this.handleBinaryData(data);
    }
    /**
     * Fetches data from a URL and parses it as JSON.
     * @param pURL - The URL to fetch the data from.
     * @returns A promise that resolves to the parsed JSON data.
     */
    private async fetchAndParseJSON(pURL: string): Promise<any> {
        try {
            const response = await fetch(pURL);
            const jsonData = await response.json();
            return jsonData;
        } catch (pError) {
            throw new Error(`Failed to fetch or parse JSON from URL: ${pError}`);
        }
    }
    /**
     * Handles binary data (ArrayBuffer or Uint8Array). Attempts to inflate or decode it.
     * @param pBinaryData - The binary data to process.
     * @returns The parsed JSON object or decoded string, or null if it fails.
     */
    private handleBinaryData(pBinaryData: ArrayBuffer | Uint8Array): any | null {
        const byteArray = pBinaryData instanceof ArrayBuffer ? new Uint8Array(pBinaryData) : pBinaryData;

        try {
            // Try pako decompression first
            const decompressed = pako.inflate(byteArray, { to: 'string' });
            if (!decompressed) return null;
            return JSON.parse(decompressed);
        } catch (pError) {
            // Fallback attempt to decode directly as UTF-8 string
            try {
                const decodedText = new TextDecoder().decode(byteArray);
                if (!decodedText) return null;
                return JSON.parse(decodedText);
            } catch (pDecodeError) {
                console.error('Decoding failed:', pDecodeError);
                return null; // Return null if both decompression and decoding fail
            }
        }
    }

    /**
     * Processes the parsed VYI data and adds icons to the VYI module instance.
     * @param pVyi - The parsed VYI data.
     */
    private processVyiData(pVyi: VyiData): void {
        this.icons.clear(); // Clear existing icons before processing new data
        // @ts-ignore - Handle old format
        const icons = pVyi.i || pVyi.icons;
        this.formatVersion = pVyi.v ?? 'format not found';

        if (Array.isArray(icons)) {
            icons.forEach((pIconData: any) => {
                if (!Array.isArray(pIconData) && typeof pIconData === 'object') {
                    // Convert old object format to new array format
                    const convertedIconData = this.convertOldIconData(pIconData);
                    this.addIcon(convertedIconData);
                } else {
                    this.addIcon(pIconData);
                }
            });
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid .vyi file! Cannot parse icons.');
        }
    }

    /**
     * Converts old object-based icon data to the new array-based format.
     * @param pOldData - The old format icon data object.
     * @returns The converted IconData array.
     */
    private convertOldIconData(pOldData: any): IconData {
        // Convert frames
        const frames = Array.isArray(pOldData.frames)
            ? pOldData.frames.map((f: any) => [f.data, f.delay])
            : [];

        // Convert states
        const states = Array.isArray(pOldData.states)
            ? pOldData.states.map((s: any) => {
                const stateFrames = Array.isArray(s.frames)
                    ? s.frames.map((f: any) => [f.data, f.delay])
                    : [];
                return [s.name, s.data, s.delay || 100, stateFrames];
            })
            : [];

        return [
            pOldData.name || '',
            pOldData.w || 32,
            pOldData.h || 32,
            pOldData.delay || 100,
            pOldData.data || '',
            frames,
            states
        ] as any;
    }
    /**
     * Adds an icon to this VYI.
     * @param pIconData - The icon data to use.
     * @returns The Icon added or undefined.
     */
    addIcon(pIconData: Icon | IconData): Icon | undefined {
        if (!pIconData) {
            VYI.logger.prefix('Vyi-module').error('No icon data passed!');
            return;
        }

        if (!(pIconData instanceof Icon) && !Array.isArray(pIconData)) {
            VYI.logger.prefix('Vyi-module').error('Invalid icon data type passed!');
            return;
        }

        const icon = pIconData instanceof Icon
            ? pIconData
            : new Icon(pIconData);

        this.icons.set(icon.id, icon);
        icon.setVyi(this);
        return icon;
    }
    /**
     * Removes the icon passed.
     * @param pIcon - The icon to remove from this vyi.
     */
    removeIcon(pIcon: Icon): void {
        if (!pIcon) return;
        if (pIcon instanceof Icon) {
            if (this.icons.delete(pIcon.id)) {
                pIcon.removeVyi();
            }
        }
    }
    /**
     * Removes the icon via it's name. The LAST defined icon that has the passed name will be removed. As names are not unique.
     * @param pName - The name to use to find the icon.
     */
    removeIconByName(pName: string): void {
        const icon = this.getIcon(pName);
        if (icon) {
            this.removeIcon(icon);
        }
    }
    /**
     * Removes the icon via it's id.
     * @param pId - The id to use to find the icon.
     */
    removeIconById(pId: string): void {
        const icon = this.getIconById(pId);
        if (icon) {
            this.removeIcon(icon);
        }
    }
    /**
     * Returns all the icon names in this vyi.
     * @returns An array of icon names in this vyi.
     */
    getIconNames(): string[] {
        const iconNames = this.getIcons().map((pIcon) => pIcon.name);
        return iconNames;
    }
    /**
     * Gets the icon that has the name pName. The LAST defined icon that has the passed name will be returned.
     * @param pName - The name of the icon to get.
     * @returns The icon that has the name pName or undefined.
     */
    getIcon(pName: string): Icon | undefined {
        if (typeof pName === 'string') {
            const icons = this.getIcons();
            for (let i = icons.length - 1; i >= 0; i--) {
                const icon = icons[i];
                // If the icon has the same name, return that icon
                if (icon.getName() === pName) {
                    return icon;
                }
            }
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid name type used!');
        }
    }
    /**
     * Gets the number of icons this vyi has.
     * @returns The amount of icons this vyi has.
     */
    getIconCount(): number {
        return this.icons.size;
    }
    /**
     * Gets an icon by the id provided.
     * @param pId - The id of the icon.
     * @returns The icon that has the id that was passed.
     */
    getIconById(pId: string): Icon | undefined {
        if (!pId) return;
        // We recursively check the states of the parent to get the icon if its not found on the vyi.
        const icon = this.icons.get(pId) || this.getIcons().find((pIcon) => pIcon.states.has(pId))?.getStateById(pId);
        return icon;
    }
    /**
     * Gets all the icons in this vyi.
     * @returns Array of all icons
     */
    getIcons(): Icon[] {
        return Array.from(this.icons.values());
    }
    /**
     * Renames the vyi.
     * @param pName - The name to give this vyi.
     */
    rename(pName: string): void {
        if (typeof pName === 'string') {
            this.name = pName;
        } else {
            VYI.logger.prefix('Vyi-module').error('Invalid name type used!');
        }
    }
    /**
     * Gets the name of the vyi.
     * @returns The name of the vyi.
     */
    getName(): string {
        return this.name;
    }
    /**
     * Exports this VYI into VYI format.
     * @param pCompressed - Whether the data will be compressed.
     * @returns Returns the vyi data in either a binary string or an object.
     */
    export(pCompressed?: boolean): VyiData | Uint8Array {
        const vyi: VyiData = {
            v: this.formatVersion,
            i: this.getIcons().map((pIcon) => pIcon.export())
        };
        if (pCompressed) {
            const binaryData = new TextEncoder().encode(JSON.stringify(vyi));
            const compressed = pako.deflate(binaryData);
            return compressed;
        }
        return vyi;
    }
}
